namespace $ {

	$mol_test({

		'room is counted from the host center to both edges of the view'() {
			$mol_assert_like(
				$bog_tooltip_room( { left: 12, width: 40 }, 1280 ),
				{ left: 32, right: 1248, flip: false, lift: 0 },
			)
			$mol_assert_like(
				$bog_tooltip_room( { left: 1228, width: 40 }, 1280 ),
				{ left: 1248, right: 32, flip: false, lift: 0 },
			)
		},

		'host past the right edge leaves negative room on that side'() {
			$mol_assert_like(
				$bog_tooltip_room( { left: 1270, width: 40 }, 1280 ),
				{ left: 1290, right: -10, flip: false, lift: 0 },
			)
		},

		'a host with room below keeps the tip below it'() {
			const room = $bog_tooltip_room(
				{ left: 100, width: 40, bottom: 200, height: 40 },
				1280, 800,
			)

			$mol_assert_equal( room.flip, false )
			$mol_assert_equal( room.lift, 0 )
		},

		'a host at the floor flips the tip up over its own height and the gap'() {
			const room = $bog_tooltip_room(
				{ left: 100, width: 40, bottom: 790, height: 40 },
				1280, 800,
			)

			$mol_assert_equal( room.flip, true )
			$mol_assert_equal( room.lift, 40 + $bog_tooltip_room_gap )
		},

		'a host with no room on either side keeps the tip below'() {
			const room = $bog_tooltip_room(
				{ left: 100, width: 40, bottom: 30, height: 30 },
				1280, 40,
			)

			$mol_assert_equal( room.flip, false )
		},

		'the room below is counted up to the need, not to the last pixel'() {
			const tight = $bog_tooltip_room(
				{ left: 100, width: 40, bottom: 800 - $bog_tooltip_room_need + 1, height: 40 },
				1280, 800,
			)

			const enough = $bog_tooltip_room(
				{ left: 100, width: 40, bottom: 800 - $bog_tooltip_room_need, height: 40 },
				1280, 800,
			)

			$mol_assert_equal( tight.flip, true )
			$mol_assert_equal( enough.flip, false )
		},

	})

}
